// Axon ASI demo: an executable WORLD MODEL that compresses toward the simplest
// program that fits the data.
//
// This is the frontier pattern: a program that PREDICTS, is CHECKED against
// OBSERVATIONS, and is COMPRESSED toward the simplest parameters that still fit
// (MDL / skill-acquisition efficiency). The base model is the PROPOSER; Axon is
// the fixed VERIFIER + FITNESS FUNCTION every base-model gain rides on.
//
// Loop primitives (all shipped on merge-asi-layer3):
//   * @[adaptive] + goal_run         — the search/optimizer (the proposer)
//   * fit_error vs observations      — "checked against observations"
//   * a refinement `where fit(_)`    — fit as a hard, type-level contract
//   * description_bits (MDL)         — the "measure of simplest" (cf. axon complexity)
//   * fitness = fit − λ·complexity   — compress SUBJECT TO fit (fit is the gate)
//
// Run:  axon run examples/asi/world_model.ax
//       axon complexity examples/asi/world_model.ax --json   # the program's own MDL

// ── The world: a 2-parameter linear model y = a*x + b ───────────────────────────
// (Two parameters, so "fewer/simpler parameters" is a real axis: the ground truth
//  has b = 0, and the loop should discover it does NOT need the offset.)
type World = { a: i64, b: i64, n: i64 }

@[pure]
fn predict(w: World, x: i64) -> i64 { w.a * x + w.b }

// Ground truth the search does not know: y = 3x (slope 3, NO offset).
@[pure]
fn truth(x: i64) -> i64 { 3 * x }

@[pure]
fn fit_error(w: World) -> i64 {
    let e = 0
    for i in 0..w.n {
        e = e + abs_i64(predict(w, i) - truth(i))
    }
    e
}

// Fit as a TYPE contract: a Fitted model's error is 0. Building one from
// non-fitting parameters is a refinement violation (exit 6) — the loop literally
// cannot keep a model that does not fit.
type Fitted = World where fit_error(_) <= 0

// ── The MDL term: description length of the learned parameters ───────────────────
fn description_bits(v: i64) -> i64 {
    let m = abs_i64(v)
    let bits = 1
    let rem = m
    while rem > 0 { bits = bits + 1  rem = rem / 2 }
    bits
}
// A model that uses the offset costs more to describe than one that zeroes it —
// so among equally-fitting models, the loop is pulled toward the SIMPLER (b = 0).
fn world_bits(w: World) -> i64 { description_bits(w.a) + description_bits(w.b) }

// ── The compress-to-fit objective: ONE maximizable scalar ───────────────────────
// fit dominates (×1000) so an unfit model can never out-score a fit one; the MDL
// penalty only breaks ties toward simplicity.
fn fitness(w: World) -> i64 { 100000 - 1000 * fit_error(w) - world_bits(w) }

// goal_run varies the SLOPE (leading i64 dim). We hold the offset at 0 — the
// simplest hypothesis — and let the search confirm slope 3 fits perfectly, so the
// learned model is both correct AND minimal (no offset needed).
@[adaptive(metric: learn_slope, target: 100000.0)]
fn learn_slope(a: i64) -> i64 {
    fitness(World { a: a, b: 0, n: 10 })
}

fn main() -> i64 {
    println("world model: learning y = a*x + b from 10 observations of y = 3x")

    // Compress-to-fit: hill-climb the slope to maximize fitness.
    let best_score = goal_run("learn_slope", 100000.0, 80)
    let learned_a = goal_best_input("learn_slope", 100000.0)
    let learned = World { a: learned_a, b: 0, n: 10 }

    println("  learned: a={to_str(learned_a)} b=0  (truth a=3 b=0)")
    println("  fit error:   {to_str(fit_error(learned))}")
    println("  description: {to_str(world_bits(learned))} bits  (slope + offset)")
    println("  fitness:     {to_str_f64(best_score)}")

    // Show that ADDING an unnecessary offset fits worse OR costs more bits — i.e.
    // the minimal model is genuinely preferred.
    let bloated = World { a: 3, b: 7, n: 10 }
    println("a model with a spurious offset b=7: error {to_str(fit_error(bloated))}, {to_str(world_bits(bloated))} bits")

    // The learned model fits as a TYPE: this constructs a Fitted (error 0) — or
    // would exit 6 if the search had failed. Proof the result actually fits.
    let proven: Fitted = learned
    println("verified fit: a={to_str(proven.a)}")

    fit_error(proven)   // exit 0 iff a perfectly-fitting model was found
}

@[test]
fn test_predict_linear() {
    let w = World { a: 3, b: 0, n: 10 }
    assert_eq(predict(w, 0), 0)
    assert_eq(predict(w, 4), 12)
    let v = World { a: 2, b: 5, n: 10 }
    assert_eq(predict(v, 0), 5)
    assert_eq(predict(v, -3), -1)
    assert_eq(predict(v, 10), 25)
}

@[test]
fn test_truth_is_three_x() {
    assert_eq(truth(0), 0)
    assert_eq(truth(1), 3)
    assert_eq(truth(7), 21)
    assert_eq(truth(-2), -6)
}

@[test]
fn test_predict_matches_truth_for_true_model() {
    let w = World { a: 3, b: 0, n: 10 }
    for i in 0..10 {
        assert_eq(predict(w, i), truth(i))
    }
    let off = World { a: 3, b: 1, n: 10 }
    assert_eq(predict(off, 5) - truth(5), 1)
}

@[test]
fn test_fit_error_exact_and_offset() {
    assert_eq(fit_error(World { a: 3, b: 0, n: 10 }), 0)
    assert_eq(fit_error(World { a: 3, b: 7, n: 10 }), 70)
    assert_eq(fit_error(World { a: 3, b: -2, n: 5 }), 10)
}

@[test]
fn test_fit_error_slope_and_sample_count() {
    assert_eq(fit_error(World { a: 2, b: 0, n: 10 }), 45)
    assert_eq(fit_error(World { a: 4, b: -1, n: 3 }), 2)
    assert_eq(fit_error(World { a: 0, b: 0, n: 4 }), 18)
    assert_eq(fit_error(World { a: 9, b: 9, n: 0 }), 0)
}

@[test]
fn test_description_bits_small_values() {
    assert_eq(description_bits(0), 1)
    assert_eq(description_bits(1), 2)
    assert_eq(description_bits(2), 3)
    assert_eq(description_bits(3), 3)
    assert_eq(description_bits(4), 4)
    assert_eq(description_bits(7), 4)
}

@[test]
fn test_description_bits_powers_and_sign() {
    assert_eq(description_bits(8), 5)
    assert_eq(description_bits(255), 9)
    assert_eq(description_bits(256), 10)
    assert_eq(description_bits(-8), 5)
    assert_eq(description_bits(-1), 2)
}

@[test]
fn test_world_bits_offset_costs_more() {
    assert_eq(world_bits(World { a: 3, b: 0, n: 10 }), 4)
    assert_eq(world_bits(World { a: 3, b: 7, n: 10 }), 7)
    assert_eq(world_bits(World { a: 0, b: 0, n: 10 }), 2)
    assert(world_bits(World { a: 3, b: 0, n: 10 }) < world_bits(World { a: 3, b: 1, n: 10 }))
}

@[test]
fn test_fitness_values() {
    assert_eq(fitness(World { a: 3, b: 0, n: 10 }), 99996)
    assert_eq(fitness(World { a: 3, b: 7, n: 10 }), 29993)
    assert_eq(fitness(World { a: 2, b: 0, n: 10 }), 54996)
}

@[test]
fn test_fitness_prefers_fit_then_simplicity() {
    let exact = World { a: 3, b: 0, n: 10 }
    let off = World { a: 3, b: 1, n: 10 }
    assert(fitness(exact) > fitness(off))
    assert_eq(fitness(off), 100000 - 10000 - 5)
    assert_eq(fitness(World { a: 3, b: 0, n: 0 }), 99996)
    assert_eq(fitness(World { a: 1, b: 0, n: 0 }), 99997)
}

@[test]
fn test_learn_slope_scores() {
    assert_eq(learn_slope(3), 99996)
    assert_eq(learn_slope(2), 54996)
    assert_eq(learn_slope(4), 54995)
    assert_eq(learn_slope(0), -35002)
}

@[test]
fn test_learn_slope_peak_at_true_slope() {
    let best = learn_slope(3)
    for a in -5..12 {
        if a != 3 { assert(learn_slope(a) < best) }
    }
    let proven: Fitted = World { a: 3, b: 0, n: 10 }
    assert_eq(fit_error(proven), 0)
}

// closures_demo.ax — lambdas and higher-order functions in Axon
//
// Phase 2 introduced arrow-lambda syntax.  Full closure captures (closures
// that mutate variables from the enclosing scope) are coming in Phase 3.
// This file demonstrates what works today:
//
//   • Arrow lambda syntax: (params) => expr
//   • Lambdas stored in let bindings
//   • Passing lambdas to higher-order functions
//   • Returning lambdas from functions
//   • Function composition helpers

// --- Storing a lambda in a variable ---

fn demo_basic_lambdas() {
    let double  = (x: i64) => x * 2
    let square  = (x: i64) => x * x
    let negate  = (x: i64) => 0 - x

    println("double(7)  = {to_str(double(7))}")
    println("square(7)  = {to_str(square(7))}")
    println("negate(7)  = {to_str(negate(7))}")
}

// --- Higher-order functions ---

// Apply f to every element in an implicit range [0, n) and print the result.
fn for_each_index(n: i64, f: (i64) -> i64) {
    let i = 0
    while i < n {
        println("  [{to_str(i)}] => {to_str(f(i))}")
        i = i + 1
    }
}

// map_print applies f to each element of a 3-element array and prints it.
// (Axon arrays are fixed-size; generic map is Phase 3.)
fn map3_print(label: str, a: [i64; 3], f: (i64) -> i64) {
    println("{label}:")
    let i = 0
    while i < 3 {
        println("  {to_str(a[i])} => {to_str(f(a[i]))}")
        i = i + 1
    }
}

// reduce folds a 3-element array with a binary lambda.
fn reduce3(a: [i64; 3], init: i64, f: (i64, i64) -> i64) -> i64 {
    let acc = init
    let i = 0
    while i < 3 {
        acc = f(acc, a[i])
        i = i + 1
    }
    acc
}

// --- Returning a lambda from a function ---

// Returns a lambda that adds `n` to its argument.
fn make_adder(n: i64) -> (i64) -> i64 {
    (x: i64) => x + n
}

// Returns a lambda that multiplies its argument by `factor`.
fn make_multiplier(factor: i64) -> (i64) -> i64 {
    (x: i64) => x * factor
}

fn main() -> i64 {
    println("=== Basic lambdas ===")
    demo_basic_lambdas()

    println("")
    println("=== for_each_index: squares of 0..5 ===")
    for_each_index(6, (i: i64) => i * i)

    println("")
    println("=== map3_print ===")
    let nums = [3, 5, 7]
    map3_print("double", nums, (x: i64) => x * 2)
    map3_print("square", nums, (x: i64) => x * x)

    println("")
    println("=== reduce3: sum and product ===")
    let sum  = reduce3(nums, 0, (acc: i64, x: i64) => acc + x)
    let prod = reduce3(nums, 1, (acc: i64, x: i64) => acc * x)
    println("sum     = {to_str(sum)}")    // 15
    println("product = {to_str(prod)}")   // 105

    println("")
    println("=== make_adder / make_multiplier ===")
    let add10  = make_adder(10)
    let triple = make_multiplier(3)
    println("add10(5)  = {to_str(add10(5))}")    // 15
    println("triple(7) = {to_str(triple(7))}")   // 21

    // Compose: triple then add10
    let i = 0
    println("compose triple+add10 on [1..5]:")
    while i < 5 {
        let v = i + 1
        println("  {to_str(v)} => {to_str(add10(triple(v)))}")
        i = i + 1
    }

    0
}

@[test]
fn test_reduce3_sum_and_product_documented() {
    let nums = [3, 5, 7]
    assert_eq(reduce3(nums, 0, (acc: i64, x: i64) => acc + x), 15)
    assert_eq(reduce3(nums, 1, (acc: i64, x: i64) => acc * x), 105)
}

@[test]
fn test_reduce3_uses_init_and_order() {
    let nums = [1, 2, 3]
    assert_eq(reduce3(nums, 100, (acc: i64, x: i64) => acc + x), 106)
    assert_eq(reduce3(nums, 0, (acc: i64, x: i64) => acc * 10 + x), 123)
    assert_eq(reduce3(nums, 0, (acc: i64, x: i64) => acc - x), -6)
    assert_eq(reduce3([4, 9, 2], 0, (acc: i64, x: i64) => if x > acc { x } else { acc }), 9)
}

@[test]
fn test_make_adder_documented() {
    let add10 = make_adder(10)
    assert_eq(add10(5), 15)
    assert_eq(add10(0), 10)
    assert_eq(add10(-10), 0)
    let add0 = make_adder(0)
    assert_eq(add0(42), 42)
}

@[test]
fn test_make_multiplier_documented() {
    let triple = make_multiplier(3)
    assert_eq(triple(7), 21)
    assert_eq(triple(0), 0)
    assert_eq(triple(-4), -12)
    let zero = make_multiplier(0)
    assert_eq(zero(99), 0)
}

@[test]
fn test_compose_triple_then_add10() {
    let add10 = make_adder(10)
    let triple = make_multiplier(3)
    assert_eq(add10(triple(1)), 13)
    assert_eq(add10(triple(5)), 25)
    assert_eq(triple(add10(1)), 33)
}

@[test]
fn test_reduce3_with_returned_lambdas() {
    let nums = [3, 5, 7]
    let add10 = make_adder(10)
    let double = make_multiplier(2)
    assert_eq(reduce3(nums, 0, (acc: i64, x: i64) => acc + add10(x)), 45)
    assert_eq(reduce3(nums, 0, (acc: i64, x: i64) => acc + double(x)), 30)
}

// R21 — Exact fixed-point `Decimal` money type: a double-entry ledger.
//
// THE fintech-credibility blocker: you cannot handle money on `f64`, because
// `0.1 + 0.2 != 0.3` in binary floating point. Axon's `Decimal` is an EXACT
// base-10 fixed-point number (i128 mantissa at scale 9), so money arithmetic
// is exact, checked (overflow → graceful panic), and equality/ordering are
// precise. Division specifies a rounding mode (banker's / half-even default).
//
// Literal syntax: a `d` suffix — `1.50d`, `0.1d`, `100d`.
//
// Run on the interpreter:  axon run examples/fintech/ledger.ax
// Run the test suite:      axon test examples/fintech/ledger.ax
//
// Native codegen E0910-refuses Decimal in this slice (interp-only — exact
// rounding IR is not yet wired; see governance/specs/R21-decimal.md).

// ── The headline: 0.1 + 0.2 == 0.3 EXACTLY ───────────────────────────────────

@[test]
fn test_point_one_plus_point_two_is_exact() {
    // On f64 this is false. On Decimal it is EXACTLY true.
    assert(0.1d + 0.2d == 0.3d)
}

// ── Exact add / sub / mul ─────────────────────────────────────────────────────

@[test]
fn test_exact_add() {
    assert(1.50d + 2.25d == 3.75d)
}

@[test]
fn test_exact_sub() {
    assert(10.00d - 0.01d == 9.99d)
}

@[test]
fn test_exact_mul() {
    // Price × quantity — exact, no drift.
    let price = 19.99d
    let qty = 3d
    assert(price * qty == 59.97d)
}

// ── Comparison / ordering ─────────────────────────────────────────────────────

@[test]
fn test_ordering() {
    assert(0.10d < 0.11d)
    assert(100d > 99.99d)
    assert(5.5d >= 5.5d)
    assert(2.50d != 2.5000001d)
}

// ── Division with rounding modes ──────────────────────────────────────────────

@[test]
fn test_div_truncate_vs_half_even() {
    // 1 / 3 at scale 9.
    let down = decimal_div(1d, 3d, "down")
    assert(decimal_to_str(down) == "0.333333333")
    // 2 / 3 rounds the last digit up under half-even.
    let he = decimal_div(2d, 3d, "half_even")
    assert(decimal_to_str(he) == "0.666666667")
}

@[test]
fn test_round_banker() {
    // Banker's rounding (half to even): 1.005 → 1.00, 1.015 → 1.02.
    assert(decimal_round(1.005d, 2, "half_even") == 1.00d)
    assert(decimal_round(1.015d, 2, "half_even") == 1.02d)
}

// ── Parse / format round-trip ─────────────────────────────────────────────────

@[test]
fn test_parse_format_round_trip() {
    match decimal_from_str("1234.56") {
        Ok(d) => assert(decimal_to_str(d) == "1234.56")
        Err(e) => assert(false)
    }
    // Excess precision (>9 fractional digits) is a clean Err, not a panic.
    match decimal_from_str("1.0000000001") {
        Ok(d) => assert(false)
        Err(e) => assert(true)
    }
}

// ── abs / neg ─────────────────────────────────────────────────────────────────

@[test]
fn test_abs_neg() {
    assert(decimal_abs(0d - 5.5d) == 5.5d)
    assert(decimal_neg(5.5d) == 0d - 5.5d)
}

// ── Double-entry posting: debits + credits sum to ZERO exactly ────────────────

// A balanced journal entry: debits are positive, credits negative, so the
// signed sum of all four legs is exactly zero. On f64 a sum of many fractional
// postings drifts; on Decimal it is exactly 0.
//
// Legs: +debit1, -credit1, +debit2, -credit2.
fn journal_balance(debit1: Decimal, credit1: Decimal, debit2: Decimal, credit2: Decimal) -> Decimal {
    (debit1 - credit1) + (debit2 - credit2)
}

@[test]
fn test_double_entry_sums_to_zero() {
    // Cash 100.33 debit ↔ Revenue 100.33 credit; Tax 7.07 debit ↔ Liability 7.07 credit.
    let total = journal_balance(100.33d, 100.33d, 7.07d, 7.07d)
    assert(total == 0d)
}

// ── Balance refinement: an overdraft is REJECTED (exit 6) ─────────────────────

// `where _ >= 0d` is a non-negative-balance invariant enforced at the binding
// site. A withdrawal that overdraws the account fails the refinement at runtime
// (exit 6, REFINE_VIOLATION) — the compiler refuses to let an invalid balance
// exist, rather than silently producing a negative number.
fn withdraw(balance: Decimal, amount: Decimal) -> Decimal {
    let new_balance: Decimal where _ >= 0d = balance - amount
    new_balance
}

@[test]
fn test_withdraw_within_balance_ok() {
    assert(withdraw(100d, 30d) == 70.00d)
}

// ── Demo main: a tiny ledger run ──────────────────────────────────────────────

fn main() {
    println("== Axon Decimal ledger ==")
    println("0.1d + 0.2d         = {decimal_to_str(0.1d + 0.2d)}   (== 0.3d ? {to_str(0.1d + 0.2d == 0.3d)})")
    println("19.99d * 3d         = {decimal_to_str(19.99d * 3d)}")
    println("1d / 3d (half_even) = {decimal_to_str(decimal_div(1d, 3d, \"half_even\"))}")

    // Double-entry: balanced journal sums to zero.
    let total = journal_balance(100.33d, 100.33d, 7.07d, 7.07d)
    println("balanced journal    = {decimal_to_str(total)}   (zero ? {to_str(total == 0d)})")

    // A legal withdrawal.
    let bal = withdraw(100d, 30d)
    println("balance after -30   = {decimal_to_str(bal)}")

    // The overdraft below would trigger the `where _ >= 0d` refinement and exit 6.
    // Uncomment to see the runtime rejection:
    // let overdrawn = withdraw(100d, 150d)
    // println("overdrawn = {decimal_to_str(overdrawn)}")
    println("(an overdraft would be rejected by the `where _ >= 0d` refinement, exit 6)")
}

@[test]
fn test_journal_balance_unbalanced_entries() {
    assert(journal_balance(10d, 3d, 2d, 1d) == 8d)
    assert(journal_balance(0d, 5.25d, 0d, 0d) == 0d - 5.25d)
    assert(journal_balance(0.1d, 0d, 0.2d, 0d) == 0.3d)
    assert(journal_balance(0d, 0d, 0d, 0d) == 0d)
}

@[test]
fn test_journal_balance_cross_balanced_legs() {
    assert(journal_balance(50.50d, 20.25d, 0d, 30.25d) == 0d)
    assert(journal_balance(1.01d, 0.01d, 0.99d, 1.99d) == 0d)
    assert(journal_balance(100d, 0d, 0d, 0.01d) == 99.99d)
}

@[test]
fn test_withdraw_exact_amounts() {
    assert(withdraw(10.00d, 0.01d) == 9.99d)
    assert(withdraw(19.99d, 9.99d) == 10d)
    assert(withdraw(100d, 0d) == 100d)
    assert(withdraw(0.3d, 0.1d) == 0.2d)
}

@[test]
fn test_withdraw_to_exactly_zero_is_allowed() {
    assert(withdraw(5.5d, 5.5d) == 0d)
    assert(withdraw(0d, 0d) == 0d)
    assert(withdraw(withdraw(100d, 60d), 40d) == 0d)
}

// escalation.ax — a bug Axon does NOT prevent (the CONTAINED column made concrete).
//
// CVE-2024-2771 (Fluent Forms, CWE-862): privilege escalation via a MISSING capability
// check on the `/managers` endpoint — a low-privilege user adds themselves as a manager
// because the handler never verifies the caller is an admin.
//
// This is application LOGIC, not a capability violation, so Axon does not catch it — and
// it shouldn't pretend to. The point of this exemplar is the OTHER half of the story:
// the bug fires here (this program compiles AND runs, and the escalation succeeds), but
// the capability boundary caps what the escalated foothold is worth — see
// escalation_exfil.ax, where weaponizing it is a compile error.

// The (broken) authorization. The real CVE simply forgot the check; we model "no check"
// as a predicate that always passes. The compiler has no way to know this is wrong —
// it is a missing business rule, not a forbidden effect.
fn caller_is_admin(_caller_role: i64) -> bool {
    // BUG (CVE-2024-2771): the capability check is missing — anyone proceeds.
    // (Intended: `_caller_role == 1`. As shipped: no check at all.)
    true
}

@[contained(fs: [read("./public/")], net: [], exec: none)]
fn add_manager(caller_role: i64, target_user: str) -> str {
    if caller_is_admin(caller_role) {
        "GRANTED: {target_user} is now a manager"
    } else {
        "DENIED"
    }
}

fn main() -> i64 {
    // A plain subscriber (role 0) calls the endpoint and escalates themselves.
    let result = add_manager(0, "attacker")
    println(result) // prints GRANTED — Axon did NOT prevent the escalation
    println("^ the privilege-escalation LOGIC bug fired (OUT OF SCOPE for the compiler).")
    println("  Now see escalation_exfil.ax: turning this foothold into theft is REFUSED.")
    0
}

@[test]
fn test_caller_is_admin_has_no_check() {
    assert(caller_is_admin(0))
    assert(caller_is_admin(1))
    assert(caller_is_admin(-1))
    assert(caller_is_admin(99))
}

@[test]
fn test_add_manager_grants_subscriber() {
    assert(add_manager(0, "attacker") == "GRANTED: attacker is now a manager")
    assert(add_manager(1, "alice") == "GRANTED: alice is now a manager")
    assert(add_manager(0, "") == "GRANTED:  is now a manager")
}

@[test]
fn test_add_manager_never_denies() {
    assert(add_manager(7, "bob") != "DENIED")
    assert(str_starts_with(add_manager(-5, "eve"), "GRANTED: eve"))
    assert(str_ends_with(add_manager(2, "x"), " is now a manager"))
}

// brief-gate.ax — validates an agent brief before it enters the ledger workflow.
//
// A "brief" is a JSON object with required fields: goal, constraints, metric.
// Returns 0 (PASS) or 1 (FAIL) — usable as a deploy gate or subagent check.
//
// Run:  axon run examples/goals/brief-gate.ax
//       BRIEF='{"goal":"...","constraints":"...","metric":"..."}' axon run ...

fn check_field(json: str, key: str) -> Result<str, str> {
    match json_get_str(json, key) {
        Ok(v) => {
            if str_len(v) < 5 {
                Err("field '{key}' is too short (< 5 chars)")
            } else {
                Ok(v)
            }
        }
        Err(e) => Err("missing or invalid field '{key}': {e}")
    }
}

fn gate_brief(brief_json: str) -> i64 {
    match json_parse(brief_json) {
        Err(e) => {
            eprintln("BRIEF-GATE FAIL: invalid JSON — {e}")
            1
        }
        Ok(_) => {
            let goal_r        = check_field(brief_json, "goal")
            let constraints_r = check_field(brief_json, "constraints")
            let metric_r      = check_field(brief_json, "metric")

            let goal_ok = match goal_r        { Ok(_) => 1  Err(_) => 0 }
            let con_ok  = match constraints_r { Ok(_) => 1  Err(_) => 0 }
            let met_ok  = match metric_r      { Ok(_) => 1  Err(_) => 0 }

            if goal_ok == 0 {
                let msg = match goal_r { Ok(v) => v  Err(e) => e }
                eprintln("BRIEF-GATE FAIL: {msg}")
                1
            } else if con_ok == 0 {
                let msg = match constraints_r { Ok(v) => v  Err(e) => e }
                eprintln("BRIEF-GATE FAIL: {msg}")
                1
            } else if met_ok == 0 {
                let msg = match metric_r { Ok(v) => v  Err(e) => e }
                eprintln("BRIEF-GATE FAIL: {msg}")
                1
            } else {
                let goal   = match goal_r   { Ok(v) => v  Err(e) => e }
                let metric = match metric_r { Ok(v) => v  Err(e) => e }
                println("BRIEF-GATE PASS")
                println("  goal:   {goal}")
                println("  metric: {metric}")
                0
            }
        }
    }
}

// Build a JSON object string from key=value pairs.
// Uses chr(34)='"', chr(123)='{', chr(125)='}' to avoid interpolation ambiguity.
fn make_brief(goal: str, constraints: str, metric: str) -> str {
    let q = chr(34)
    let ob = chr(123)
    let cb = chr(125)
    let colon = ": "
    let comma = ", "
    let k_goal = axon_concat(q, axon_concat("goal", q))
    let k_con  = axon_concat(q, axon_concat("constraints", q))
    let k_met  = axon_concat(q, axon_concat("metric", q))
    axon_concat(ob, axon_concat(
        axon_concat(k_goal, axon_concat(colon, json_stringify(goal))),
        axon_concat(comma,
            axon_concat(
                axon_concat(k_con, axon_concat(colon, json_stringify(constraints))),
                axon_concat(comma,
                    axon_concat(k_met, axon_concat(colon, axon_concat(json_stringify(metric), cb)))
                )
            )
        )
    ))
}

fn main() -> i64 {
    println("=== Axon Brief Gate ===")
    println("")

    // Check for BRIEF env var first (subagent usage)
    let brief_from_env = match env_var("BRIEF") {
        Ok(v) => v
        Err(_) => ""
    }

    if str_len(brief_from_env) > 0 {
        println("-- brief from BRIEF env var --")
        let r = gate_brief(brief_from_env)
        r
    } else {
        // Demo mode: test valid and invalid briefs
        let valid_brief = make_brief(
            "maximize provenance ledger recall above 0.75",
            "must not ingest PII without scrubbing first",
            "recall@200 commits >= 0.75"
        )
        println("-- valid brief --")
        let r1 = gate_brief(valid_brief)
        println("")

        let invalid_brief = make_brief("ok", "yes", "num")
        println("-- invalid brief (all fields too short) --")
        let r2 = gate_brief(invalid_brief)
        println("")

        if r1 == 0 && r2 == 1 {
            println("Gate logic: CORRECT")
            0
        } else {
            println("Gate logic: WRONG (r1={to_str(r1)}, r2={to_str(r2)})")
            1
        }
    }
}

