    assert(b == "{{\"goal\": \"alpha\", \"constraints\": \"beta\", \"metric\": \"gamma\"}}")
    let short = make_brief("ok", "yes", "num")
    assert(short == "{{\"goal\": \"ok\", \"constraints\": \"yes\", \"metric\": \"num\"}}")
