    let mid = roas_with_confidence(299)
    assert_eq(mid.value, 299)
    assert(abs_f64(mid.confidence - 0.78) < 0.000001)
    let mid2 = roas_with_confidence(240)
    assert(abs_f64(mid2.confidence - 0.78) < 0.000001)
