// R25 — Axon running AS a Zephyr application on an ARM Cortex-M target.
//
// This is a *freestanding* Axon object (no libc, no axon-rt) that links into a
// minimal Zephyr application. The Zephyr C `main()` calls the Axon `@[entry]`
// function `axon_main`, which computes something real and prints it to the
// Zephyr console via the host-provided hook `zephyr_console_putc` (lowers to an
// extern C `axon_console_putc(int)` that the Zephyr app wires to `printk`).
//
// It deliberately uses ONLY scalar arithmetic + the console-byte HAL hook — no
// `str`/array builtins, because those pull in axon-rt runtime externs that a
// freestanding (no-host) image does not link. Output is emitted byte by byte,
// the same discipline as the R17 x86 kernel demo.
//
// Build the object:
//   axon build --freestanding --target zephyr --emit-obj examples/zephyr/app.ax \
//       --out /tmp/axon_app.o
//
// Then link it into the Zephyr app (examples/zephyr/CMakeLists.txt) and run
// under QEMU (`west build -t run`). See scripts/zephyr_qemu_gate.sh.
//
// The headline: a real Axon computation (a refinement-checked sensor average)
// runs on a Cortex-M RTOS under QEMU and produces verifiable console output.

substrate

// ── HAL: the console boundary (the only impure surface) ──────────────────────

// Write one byte to the Zephyr console. Lowers to extern C axon_console_putc.
@[hal]
@[no_alloc]
fn putc(b: i64) | {Hal} {
    zephyr_console_putc(b)
}

// Print a non-negative integer in decimal, then a newline (no heap, no str).
// Emits digits high-to-low using a fixed divisor ladder; leading zeros are
// suppressed. ISR/early-boot-safe (@[no_alloc]).
@[hal]
@[no_alloc]
fn put_uint(v: i64) | {Hal} {
    let started = false
    let div = 1000000000
    while div > 0 {
        let d = (v / div) % 10
        if d != 0 {
            started = true
        }
        if started {
            putc(48 + d)   // '0' + d
        }
        div = div / 10
    }
    if started == false {
        putc(48)           // value was 0 → print a single '0'
    }
    putc(10)               // '\n'
}

// ── The real computation: an average bounded by a refinement contract ────────

// Average of four sensor readings. The return carries a refinement contract:
// the mean of readings is non-negative — the "sensor-bound" guarantee a
// medical/industrial device cares about, enforced by the type system, not a
// runtime assert the optimizer could drop.
@[no_alloc]
fn sensor_avg(a: i64, b: i64, c: i64, d: i64) -> (i64 where _ > 0) {
    (a + b + c + d) / 4
}

// ── Entry: called by the Zephyr app's main() ─────────────────────────────────

// Banner "AXON\n" emitted byte by byte (no str builtin in a freestanding image).
@[hal]
@[no_alloc]
fn banner() | {Hal} {
    putc(65)  // A
    putc(88)  // X
    putc(79)  // O
    putc(78)  // N
    putc(10)  // \n
}

@[entry]
fn axon_main() | {Hal} {
    banner()
    // Four plausible sensor readings → refinement-bounded average.
    let avg = sensor_avg(21, 23, 22, 26)
    put_uint(avg)          // expect 23
    // A second, independent computation to prove arithmetic ran on-target.
    let answer = 2 + 2 * 20    // 42
    put_uint(answer)       // expect 42
}

// A freestanding image needs a panic handler even when linked into a host RTOS;
// on Zephyr a panic just reports a byte and returns (Zephyr owns reboot).
@[panic_handler]
fn on_panic() | {Hal} {
    putc(33)  // '!'
    putc(10)  // \n
}

@[test]
fn test_sensor_avg_documented_reading() {
    assert_eq(sensor_avg(21, 23, 22, 26), 23)
    assert_eq(sensor_avg(10, 10, 10, 10), 10)
    assert_eq(sensor_avg(0, 0, 0, 0), 0)
    assert_eq(sensor_avg(100, 200, 300, 400), 250)
}

@[test]
fn test_sensor_avg_integer_division() {
    assert_eq(sensor_avg(1, 1, 1, 2), 1)
    assert_eq(sensor_avg(1, 2, 3, 5), 2)
    assert_eq(sensor_avg(0, 0, 0, 3), 0)
    assert_eq(sensor_avg(0, 0, 0, 4), 1)
}

// experiment_zone.ax — the Experiment code zone (R4)
//
// Axon has three code zones beyond plain Static code:
//   @[adaptive]        — the compiler logs every return AND feeds it to the
//                        optimizer (goal_run hill-climbs it). An optimization
//                        TARGET.
//   @[experiment(lbl)] — the compiler logs every return too (un-opt-out-able
//                        provenance, I-13), but the optimizer IGNORES it. A
//                        comparison BASELINE, never auto-promoted.
//   @[agent]           — highest trust; every action is audit-logged.
//
// Both adaptive and experiment leave a durable record in the provenance log
// (see `axon trace`), tagged with their zone. The difference is purely
// behavioral: only adaptive records steer goal_run.
//
// Run:   axon run examples/asi/experiment_zone.ax
// Then:  axon trace            # see both zones' records, tagged

// The optimization target: the compiler will hill-climb this toward a goal.
@[adaptive]
fn tuned(x: i64) -> i64 {
    100 - (x - 7) * (x + 7)      // a hill peaking at x = 7
}

// A fixed baseline we want to MEASURE against the tuned fn, but never optimize.
// It is logged (provenance), labelled "control", yet kept out of goal_run.
@[experiment("control")]
fn baseline(x: i64) -> i64 {
    5                             // a flat reference line
}

fn main() -> i64 {
    // Record a few baseline observations (these LOG but do not optimize).
    let _ = baseline(1)
    let _ = baseline(2)
    let _ = baseline(3)
    let base_in_store = goal_count("baseline")
    println("baseline in optimizer store: {to_str(base_in_store)} (expect 0)")

    // Optimize the adaptive fn toward 100. Only its records are in the store.
    let best = goal_run("tuned", 100.0, 40)
    let tuned_probes = goal_count("tuned")
    println("tuned best score: {to_str_f64(best)} (optimized toward 100)")
    println("tuned probes in store: {to_str(tuned_probes)}")

    // The experiment stayed a baseline: 0 probes drove the optimizer, even
    // though its returns are in the provenance log for `axon trace` to compare.
    base_in_store                 // => 0  (clean exit code)
}

