fn test_add_manager_grants_subscriber() {
    assert(add_manager(0, "attacker") == "GRANTED: attacker is now a manager")
    assert(add_manager(1, "alice") == "GRANTED: alice is now a manager")
    assert(add_manager(0, "") == "GRANTED:  is now a manager")
}

